package com.example.evcharging.finance.reconciliation;import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;class ReconciliationMatcherTest{@Test void exact(){var r=ReconciliationMatcher.match(new ReconciliationMatcher.LocalFact("P","T",10000,1000,"SUCCESS"),new ReconciliationMatcher.ChannelFact("P","T",10000,1000,"SUCCESS"));assertEquals(ReconciliationResultType.MATCH,r.type());}@Test void oneCent(){var r=ReconciliationMatcher.match(new ReconciliationMatcher.LocalFact("P","T",10000,0,"SUCCESS"),new ReconciliationMatcher.ChannelFact("P","T",9999,0,"SUCCESS"));assertEquals(ReconciliationResultType.AMOUNT_MISMATCH,r.type());assertEquals(-1,r.differenceAmountFen());}}